function g(t){let r=Math.floor(t/60),n=t%60;return`${String(r).padStart(2,`0`)}:${String(n).padStart(2,`0`)}`}function u(t){let[r,n]=t.split(`:`).map(e=>parseInt(e,10)||0);return r*60+n}var s=[`CN`,`T2`,`T3`,`T4`,`T5`,`T6`,`T7`];function c(t){return s[new Date(t+`T00:00:00`).getDay()]}function i(t,r){let n=new Date(t+`T00:00:00`);n.setDate(n.getDate()+r);return`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,`0`)}-${String(n.getDate()).padStart(2,`0`)}`}function p(t){return new Date(t+`T00:00:00`).getDate()}function d(t){if(t<60)return`${t} ph\xFAt`;let r=Math.floor(t/60),n=t%60;return n===0?`${r}h`:`${r}h${String(n).padStart(2,`0`)}`}function f(){let t=new Date,r=String(t.getMonth()+1).padStart(2,`0`),n=String(t.getDate()).padStart(2,`0`);return`${t.getFullYear()}-${r}-${n}`}function S(t){return i(t,-((new Date(t+`T00:00:00`).getDay()+6)%7))}function m(t){let[,r,n]=t.split(`-`);return`${n}/${r}`}export{g as a,p as c,f as i,u as l,c as n,i as o,d as r,m as s,S as t};